275.   <script>
276.     const quizQuestions = [
277.       {
278.         id: "q1",
279.         legend: "1. Which of these are commonly used for web browsers?",
280.         helpText: "Select every language that is routinely used to build browser-based experiences.",
281.         options: [
282.           { id: "q1-html", label: "HTML" },
283.           { id: "q1-javascript", label: "JavaScript" },
284.           { id: "q1-python", label: "Python" },
285.           { id: "q1-css", label: "CSS" }
286.         ]
287.       },
288.       {
289.         id: "q2",
290.         legend: "2. Which languages are generally considered compiled languages?",
291.         options: [
292.           { id: "q2-cpp", label: "C++" },
293.           { id: "q2-go", label: "Go" },
294.           { id: "q2-ruby", label: "Ruby" },
295.           { id: "q2-rust", label: "Rust" }
296.         ]
297.       },
298.       {
299.         id: "q3",
300.         legend: "3. Which of these languages are often used for data analysis or scientific computing?",
301.         options: [
302.           { id: "q3-python", label: "Python" },
303.           { id: "q3-r", label: "R" },
304.           { id: "q3-sql", label: "SQL" },
305.           { id: "q3-swift", label: "Swift" }
306.         ]
307.       }
308.     ];
309. 
310.     function CheckboxOption(option, name) {
311.       return `
312.         <div class="choice">
313.           <input id="${option.id}" type="checkbox" name="${name}" value="${option.label}">
314.           <label for="${option.id}">${option.label}</label>
315.         </div>
316.       `;
317.     }
318. 
319.     function QuestionCard(question, index) {
320.       const describedBy = [];
321. 
322.       if (question.helpText) {
323.         describedBy.push(question.id + "-help");
324.       }
325. 
326.       return `
327.         <div class="form-field">
328.           <fieldset${describedBy.length ? ` aria-describedby="${describedBy.join(" ")}"` : ""}>
329.             <legend>${question.legend}</legend>
330.             ${question.helpText ? `<p id="${question.id}-help" class="question-help">${question.helpText}</p>` : ""}
331.             ${index === quizQuestions.length - 1 ? `<p class="question-note">More than one answer may be correct for every question.</p>` : ""}
332.             <div class="choice-list">
333.               ${question.options.map((option) => CheckboxOption(option, question.id)).join("")}
334.             </div>
335.           </fieldset>
336.         </div>
337.       `;
338.     }
339. 
340.     function ResultsPanel() {
341.       return `
342.         <section class="results" aria-labelledby="results-heading">
343.           <h2 id="results-heading">Submitted selections</h2>
344.           <ol id="results-list" class="results-list"></ol>
345.         </section>
346.       `;
347.     }
348. 
349.     function QuizForm() {
350.       return `
351.         <form id="quiz-form">
352.           ${quizQuestions.map((question, index) => QuestionCard(question, index)).join("")}
353.           <div class="actions">
354.             <button type="submit">Submit quiz</button>
355.             <div id="form-status" class="status-region" role="status" aria-atomic="true"></div>
356.           </div>
357.           ${ResultsPanel()}
358.         </form>
359.       `;
360.     }
361. 
362.     function App() {
363.       return `
364.         <div class="page-shell">
365.           <header>
