 <body>
   <a class="skip-link" href="#maincontent">Skip to main content</a>
   <div id="app"></div>

   <script>
     const quizQuestions = [
       {
         id: "q1",
         legend: "1. Which of these are commonly used for web browsers?",
         helpText: "Select every language that is routinely used to build browser-based experiences.",
         options: [
           { id: "q1-html", label: "HTML" },
           { id: "q1-javascript", label: "JavaScript" },
           { id: "q1-python", label: "Python" },
           { id: "q1-css", label: "CSS" }
         ]
       },
       {
         id: "q2",
         legend: "2. Which languages are generally considered compiled languages?",
         options: [
           { id: "q2-cpp", label: "C++" },
           { id: "q2-go", label: "Go" },
           { id: "q2-ruby", label: "Ruby" },
           { id: "q2-rust", label: "Rust" }
         ]
       },
       {
         id: "q3",
         legend: "3. Which of these languages are often used for data analysis or scientific computing?",
         options: [
           { id: "q3-python", label: "Python" },
           { id: "q3-r", label: "R" },
           { id: "q3-sql", label: "SQL" },
           { id: "q3-swift", label: "Swift" }
         ]
       }
     ];

     function CheckboxOption(option, name) {
       return `
         <div class="choice">
           <input id="${option.id}" type="checkbox" name="${name}" value="${option.label}">
           <label for="${option.id}">${option.label}</label>
         </div>
       `;
     }

     function QuestionCard(question, index) {
       const describedBy = [];

       if (question.helpText) {
         describedBy.push(question.id + "-help");
       }

       return `
         <div class="form-field">
           <fieldset${describedBy.length ? ` aria-describedby="${describedBy.join(" ")}"` : ""}>
             <legend>${question.legend}</legend>
             ${question.helpText ? `<p id="${question.id}-help" class="question-help">${question.helpText}</p>` : ""}
             ${index === quizQuestions.length - 1 ? `<p class="question-note">More than one answer may be correct for every question.</p>` : ""}
             <div class="choice-list">
               ${question.options.map((option) => CheckboxOption(option, question.id)).join("")}
             </div>
           </fieldset>
         </div>
       `;
     }

     function ResultsPanel() {
       return `
         <section class="results" aria-labelledby="results-heading">
           <h2 id="results-heading">Submitted selections</h2>
           <ol id="results-list" class="results-list"></ol>
         </section>
       `;
     }

     function QuizForm() {
       return `
         <form id="quiz-form">
           ${quizQuestions.map((question, index) => QuestionCard(question, index)).join("")}
           <div class="actions">
             <button type="submit">Submit quiz</button>
             <div id="form-status" class="status-region" role="status" aria-atomic="true"></div>
           </div>
           ${ResultsPanel()}
         </form>
       `;
     }

     function App() {
       return `
         <div class="page-shell">
           <header>
             <p class="eyebrow">Interactive quiz</p>
           </header>
           <main id="maincontent" tabindex="-1">
             <h1>Computer Languages Quiz</h1>
             <p class="intro">Choose all answers that apply for each question, then submit to review your selections.</p>
             <section class="quiz-card" aria-labelledby="quiz-section-title">
               <h2 id="quiz-section-title" class="sr-only">Quiz questions</h2>
               ${QuizForm()}
             </section>
           </main>
         </div>
       `;
     }

     function renderApp() {
       document.getElementById("app").innerHTML = App();
     }

     function attachFormBehavior() {
       const form = document.getElementById("quiz-form");
       const status = document.getElementById("form-status");
       const resultsList = document.getElementById("results-list");

       form.addEventListener("submit", function (event) {
         event.preventDefault();

         const formData = new FormData(form);
         const summaries = quizQuestions.map((question) => {
           const answers = formData.getAll(question.id);
           return {
             legend: question.legend,
             answers
           };
         });

         resultsList.innerHTML = summaries
           .map((summary) => {
             const answerText = summary.answers.length ? summary.answers.join(", ") : "No answers selected";
             return `<li><strong>${summary.legend}</strong><br>${answerText}</li>`;
           })
           .join("");

         const totalSelections = summaries.reduce((count, summary) => count + summary.answers.length, 0);
         status.textContent = totalSelections
           ? "Quiz submitted. Your selections are listed below."
           : "Quiz submitted. No answers were selected.";
       });
     }

     renderApp();
     attachFormBehavior();
   </script>
 </body>
